<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import SideNav from '../components/SideNav.vue'
import { listRequests, STATUS_LABELS, DEADLINE_LABELS, formatRupiah } from '../lib/api'
const router=useRouter(), rows=ref([]), loading=ref(true), q=ref(''), filter=ref('all')
const list=computed(()=>rows.value.filter(r=>(filter.value==='all'||r.status===filter.value)&&`${r.order_no} ${r.customer_name} ${r.description}`.toLowerCase().includes(q.value.toLowerCase())))
const cls=s=>s==='review'?'bg-tertiary-container text-on-tertiary':s==='working'?'bg-primary-container text-on-primary-container':'bg-surface-container-high text-on-surface-variant'
onMounted(async()=>{try{rows.value=await listRequests()}finally{loading.value=false}})
</script>
<template><SideNav><div class="flex flex-col md:flex-row md:items-end justify-between gap-4 mb-8"><div><p class="text-label-sm text-electric-blue uppercase tracking-wider mb-2">Workspace</p><h1 class="text-headline-lg font-bold">All Requests</h1><p class="text-secondary mt-2">Kelola dan pantau semua request project.</p></div><button @click="router.push('/request')" class="h-11 px-5 rounded-lg bg-accent-fill text-white font-bold">+ Kirim Project</button></div><div class="bg-surface-white rounded-xl p-4 shadow-md mb-6 flex flex-col sm:flex-row gap-3"><input v-model="q" placeholder="Cari order, customer, atau project..." class="flex-1 min-w-0 h-11 rounded-lg border border-outline-variant px-4 outline-none focus:border-electric-blue"><select v-model="filter" class="h-11 rounded-lg border border-outline-variant px-3 bg-white"><option value="all">Semua status</option><option v-for="(label,key) in STATUS_LABELS" :key="key" :value="key">{{label}}</option></select></div><div v-if="loading" class="text-center p-10"><span class="material-symbols-outlined animate-spin text-electric-blue text-4xl">progress_activity</span></div><div v-else-if="!list.length" class="bg-surface-white rounded-xl p-12 text-center text-secondary">Tidak ada request yang cocok.</div><div v-else class="bg-surface-white rounded-xl shadow-md overflow-hidden"><div class="hidden md:block overflow-x-auto"><table class="w-full text-left"><thead class="bg-surface text-label-sm text-secondary uppercase"><tr><th class="p-4">Order</th><th class="p-4">Customer</th><th class="p-4">Kategori</th><th class="p-4">Deadline</th><th class="p-4">Status</th><th class="p-4">Quote</th></tr></thead><tbody class="divide-y divide-border-subtle"><tr v-for="r in list" :key="r.id" @click="router.push('/requests/'+r.id)" class="hover:bg-surface-container-low cursor-pointer"><td class="p-4 font-bold">#{{r.order_no}}</td><td class="p-4">{{r.customer_name}}</td><td class="p-4 capitalize">{{r.category}}</td><td class="p-4">{{r.deadline_date ? new Date(r.deadline_date).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}) : DEADLINE_LABELS[r.deadline]}}</td><td class="p-4"><span class="px-2 py-1 rounded-full text-xs" :class="cls(r.status)">{{STATUS_LABELS[r.status]}}</span></td><td class="p-4">{{r.quote_amount?formatRupiah(r.quote_amount):'—'}}</td></tr></tbody></table></div><div class="md:hidden divide-y divide-border-subtle"><div v-for="r in list" :key="r.id" @click="router.push('/requests/'+r.id)" class="p-5"><div class="flex justify-between"><b>#{{r.order_no}}</b><span class="px-2 py-1 rounded-full text-xs" :class="cls(r.status)">{{STATUS_LABELS[r.status]}}</span></div><p class="mt-2">{{r.customer_name}} · {{r.category}}</p><p class="text-sm text-secondary mt-1">{{r.description}}</p></div></div></div></SideNav></template>
